import { projectUsageMetricsService } from '../agents/project_usage_metrics_service';
import { configService } from '../config/config_service';
import type { AgentProfile } from '../../data/agent_profiles';
import { register } from '../service_injector';
import { ProjectStatsLoader, type StatsCalculator } from './project_stats_loader';
import {
    INITIAL_SNAPSHOT,
    type LoadedStatsSource,
    type ProjectStatsSnapshot,
    type StatsCardDescriptor,
    type StatsControls,
    type StatsProjectBinding,
} from './project_stats_types';
import { buildSnapshot } from './stats_snapshot_builder';

function isValidIsoTimestamp(value: string) {
    const milliseconds = Date.parse(value);

    return Number.isFinite(milliseconds) && new Date(milliseconds).toISOString() === value;
}

function validateRangeTimestamp(value: string | null, field: string) {
    if (value !== null && !isValidIsoTimestamp(value)) throw new Error(`Invalid stats ${field}`);
}

/** Owns the stats viewing session: binding, load coordination, control updates, and snapshot notifications. */
export class ProjectStatsService extends EventTarget {
    private abortController: AbortController | null = null;
    private readonly loader: ProjectStatsLoader;
    private loadRevision = 0;
    private binding: StatsProjectBinding | null = null;
    private cards: StatsCardDescriptor[] = [];
    private isOpen = false;
    private projectKey: string | null = null;
    private snapshot = INITIAL_SNAPSHOT;
    private source: LoadedStatsSource | null = null;

    constructor(calculateStats?: StatsCalculator) {
        super();
        this.loader = new ProjectStatsLoader(calculateStats);
    }

    getSnapshot = () => this.snapshot;

    subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener);

        return () => this.removeEventListener('changed', listener);
    };

    bindProject(binding: StatsProjectBinding) {
        const projectKey = `${binding.project.id}:${binding.project.branch}`;
        if (projectKey !== this.projectKey) this.clear();
        this.projectKey = projectKey;
        this.binding = binding;
    }

    clear() {
        this.close();
        this.binding = null;
        this.projectKey = null;
    }

    async open(cards: StatsCardDescriptor[], agentProfiles: AgentProfile[] = configService.get('desktop.agentProfiles')) {
        if (!this.binding) throw new Error('Project stats are not bound to a project');
        if (this.isOpen) return;
        this.cards = cards;
        this.isOpen = true;
        this.abortController = new AbortController();
        await this.load(this.binding, agentProfiles, this.abortController.signal);
    }

    close() {
        this.loadRevision += 1;
        this.abortController?.abort();
        this.abortController = null;
        this.cards = [];
        this.isOpen = false;
        this.source = null;
        projectUsageMetricsService.clear();
        this.publish({ ...INITIAL_SNAPSHOT, controls: this.snapshot.controls });
    }

    setControls(changes: Partial<StatsControls>) {
        const controls = { ...this.snapshot.controls, ...changes };
        validateRangeTimestamp(controls.startUtc, 'startUtc');
        validateRangeTimestamp(controls.endUtc, 'endUtc');
        if (controls.startUtc && controls.endUtc && Date.parse(controls.startUtc) > Date.parse(controls.endUtc)) {
            throw new Error('Stats start date must not be after end date');
        }
        if (!this.source) {
            this.publish({ ...this.snapshot, controls });
            return;
        }

        this.publish(buildSnapshot(this.source, controls));
    }

    private async load(binding: StatsProjectBinding, agentProfiles: AgentProfile[], signal: AbortSignal) {
        const revision = ++this.loadRevision;
        const isCurrent = () => this.isCurrentLoad(revision, binding, signal);
        this.publish({ ...this.snapshot, error: null, rows: [], status: 'loading' });
        try {
            const source = await this.loader.loadSource(binding, this.cards, signal, isCurrent);
            if (!source) return;
            this.source = { ...source, agentProfiles };
            this.publish(buildSnapshot(this.source, this.snapshot.controls));
        } catch (error) {
            if (!isCurrent()) return;
            const normalizedError = error instanceof Error ? error : new Error(String(error));
            this.source = null;
            this.publish({ ...this.snapshot, error: normalizedError, rows: [], status: 'error' });
        }
    }

    private isCurrentLoad(revision: number, binding: StatsProjectBinding, signal: AbortSignal) {
        return !signal.aborted && this.isOpen && revision === this.loadRevision && binding === this.binding;
    }

    private publish(snapshot: ProjectStatsSnapshot) {
        this.snapshot = snapshot;
        this.dispatchEvent(new Event('changed'));
    }
}

export const projectStatsService = register('projectStatsService', new ProjectStatsService());

import { Box } from '@mui/material'
import { useEffect, useMemo, useRef } from 'react'
import { projectStatsService } from '../../services/stats/project_stats_service'
import type { StatsCardDescriptor } from '../../services/stats/project_stats_types'
import { useProjectState } from '../hooks/use_project_state'
import { useWorkspaceView } from '../hooks/use_workspace_view'
import { StatsContent } from './stats_content'

/** Lifetime-stable stats surface; repository reads begin only when stats mode becomes visible. */
export function StatsView() {
    const { project, snapshot } = useProjectState()
    const { viewMode } = useWorkspaceView()
    const cards = useMemo(() => {
        const projectCards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

        return projectCards.flatMap((card): StatsCardDescriptor[] => card.header.internalId ? [{
            internalId: card.header.internalId,
            path: card.path,
            title: card.header.title,
            visibleId: card.header.id,
        }] : [])
    }, [snapshot])
    const cardsRef = useRef(cards)

    useEffect(() => {
        cardsRef.current = cards
    }, [cards])

    useEffect(() => {
        if (viewMode !== 'stats' || !project) return

        void projectStatsService.open(cardsRef.current)

        return () => projectStatsService.close()
    }, [project, viewMode])

    return (
        <Box
            aria-label="Stats view"
            sx={{ bgcolor: 'background.default', display: viewMode === 'stats' ? 'flex' : 'none', flex: 1, minHeight: 0, overflow: 'hidden' }}
        >
            <StatsContent />
        </Box>
    )
}

import {
    TERMINAL_CONVERSATION_STATUSES,
    type LoadedStatsSource,
    type ProjectStatsSnapshot,
    type StatsChartRow,
    type StatsControls,
    type StatsOptions,
} from './project_stats_types';
import { activityRows } from './stats_activity_dataset';
import { buildOptions, reconcileControls } from './stats_options';
import { eligibleSamples, performanceRows, type EligibleSample } from './stats_performance_dataset';
import { inRange } from './stats_time_buckets';
import { totalsRows } from './stats_totals_dataset';
import { usageComparisonRows } from './stats_usage_comparison_dataset';

function datasetRows(
    source: LoadedStatsSource,
    controls: StatsControls,
    options: StatsOptions,
    samples: EligibleSample[],
): StatsChartRow[] {
    if (controls.dataset === 'activityOverTime') return activityRows(source, controls, controls.activityGranularity);
    if (controls.dataset === 'agentPerformance') return performanceRows(controls, samples);
    if (controls.dataset === 'usageComparison') return usageComparisonRows(source, controls, options);

    return totalsRows(source, controls);
}

function omittedTimerCount(source: LoadedStatsSource, controls: StatsControls) {
    return source.stats.conversations.filter((conversation) => (
        TERMINAL_CONVERSATION_STATUSES.has(conversation.status)
        && conversation.completedAt !== null
        && inRange(conversation.completedAt, controls)
        && conversation.elapsedMs === null
    )).length;
}

/** Reconciles controls against the loaded source, then aggregates the selected dataset once. */
export function buildSnapshot(source: LoadedStatsSource, requestedControls: StatsControls): ProjectStatsSnapshot {
    const options = buildOptions(source);
    const controls = reconcileControls(requestedControls, options);
    const performance = eligibleSamples(source, controls);
    const rows = datasetRows(source, controls, options, performance.samples);
    const excludedSampleCount = Object.values(performance.exclusionCounts).reduce((total, count) => total + count, 0);

    return {
        controls,
        error: null,
        excludedSampleCount,
        exclusionCounts: performance.exclusionCounts,
        omittedTimerCount: omittedTimerCount(source, controls),
        options,
        rows,
        status: 'ready',
        tokenTimeAvailable: source.tokenTimeAvailable,
        warnings: source.warnings,
    };
}

