function buildComparisonIndexes(
    accountRows: UsageMetricsAccountRow[],
    agentProfiles: AgentProfile[],
    tokenRows: UsageMetricsTokenRow[],
    actions: StatsActionFact[],
    granularity: StatsShortGranularity,
): ComparisonIndexes {
